var file_map = map[string]string{

	"add_scene.baml":           "class AddSceneRequest {\n  ComponentList string\n  VideoBranding VideoBranding\n}\n\nclass AddSceneResponse {\n  scene (Scene | AskUserQuestion)\n}\n\n\nfunction GenerateScene(input: AddSceneRequest, conversation_history: Message[]) -> AddSceneResponse {\n  client CustomOpenAI5WithLowThinkingSummary\n  prompt #\"\n    You are a cinematic video editor. Your job is to decompose a user query into a scene of an existing video and edit it.\n    You decide WHAT appears in scene, HOW it behaves, and WHAT data it shows.\n    You do NOT write code.\n\n     {{ input.ComponentList }}\n\n    ## SCENE DESIGN PRINCIPLES\n\n    - One idea per scene. Never combine two components in one scene.\n    - Only provide the mandatory props unless user has specifically asked for it\n    - You should always keep existing props passed in the input while editing already generated scene.\n    - If you have to replace or generate a new scene, use the component list and its props.\n\n    ## SCENE SELECTION\n    - Pick best scene which can be used to communicate the idea given in the query\n    - Only suggest fillers when user asked or a visual scene is not available\n\n    ## PLANNING RULES\n\n    ### Structure\n    - Scene has a single clear purpose. One idea per scene.\n    - Scene must stand alone. No siblings.\n    - **Define the props of scenes in SceneElement props in JSON format**\n\n    ### Data\n    - props is whatever shape the data needs — number, string, array, object, URL.\n    - Use placeholder values if real data is not provided.\n    - For images, you can use https://placehold.co/{width}x{height}.png width/height in px.\n\n    ## ALLOWED EDITS\n\n    - Change provided prop values\n    - Replace a scene with another available scene\n    - Use the `style` prop (CSS) on any component for styling\n    - Treat props with patterns like `{element}{group}-0`, `{element}{group}-1`, or `{element}--0` as arrays\n      * You may add or remove items by index\n      * Always modify all related props within the same group/index together\n\n    ## NOT ALLOWED\n\n    - Delete scenes\n    - Change duration or timings\n    - Change background\n    - Add or remove elements within a scene\n    - Modify other scenes in the video\n    - Anything outside the allowed edits\n    - The user is working in an editor where all changes are possible manually\n    - **Suggest using the editor if the request can’t be handled here**\n\n    ---\n\n    If a request can’t be fulfilled with available visuals/scenes:\n\n    1. Inform the user it can’t be generated\n    2. Suggest the closest alternative\n    3. Ask for confirmation before proceeding\n    4. Do not reveal component or scene names\n\n    ---\n\n    Do not ask about:\n    - Props or component internals — handled by the generator\n\n\n    ## ASK QUESTIONS RULES\n\n    If you lack clarity on what should visually appear in a scene, ask before proceeding.\n    Use the ask tool — do not assume missing creative direction.\n\n    Ask if:\n    - A scene implies brand presence but no brand name is provided, ask user add a brand identity\n    - Metrics are mentioned but it is unclear if they are real or placeholder\n    - An attachment is provided but you are not clear on where and how to use it using ATTACHMENT_CLARIFICATION\n    - If you think a scene needs an attachment, ask user to upload using UPLOAD_ATTACHMENT or use a placeholder\n    - Any key visual storytelling decision is ambiguous from script or attachments\n\n\n    ## EXAMPLE SCENES\n    ```json\n   // Editing an existing scene\n {\n   \"elements\": [\n     {\n       \"component\": \"IconShowcase\",\n       \"props\": \"{\\n \\\"textstagger-0\\\": { \\\"text\\\": \\\"AI models\\\" , \\\"style\\\": { \\\"textAlign\\\": \\\"center\\\"}},\\n  \\\"iconasset\\\": { \\\"icon\\\": \\\"google\\\" },\\n  \\\"textstagger-1\\\": { \\\"text\\\": \\\"Search APIs\\\" }\\n}\"\n     }\n   ]\n }\n // Generating or swapping an existing scene with a new one\n{\n  \"elements\": [\n    {\n      \"component\": \"AnimatedNumber\",\n      \"props\": \"{\\\"startText\\\": \\\"Solving\\\", \\\"endText\\\": \\\"incidents\\\", \\\"from\\\": 0, \\\"to\\\": 100}\"\n    }\n  ]\n}\n    ```\n\n    ## PLAN BEFORE EXECUTING\n\n    Before outputting scenes, reason through:\n    2. What is the narrative arc — hook, problem, solution, proof, CTA?\n    4. What data is available vs what needs a placeholder?\n    5. Are there assets that match any scene intent?\n    6. Use <attachments> and <user_note> to decide which attachment to use\n       with Asset components. Use the url directly as the value\n       in a props.\n\n    Only begin output after forming a clear plan.\n    ---\n\n    ## INPUT\n    -----\n\n    {{ BrandGuidelines(input.VideoBranding) }}\n\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
	"analyse_assets.baml":      "class AssetAnalysis {\n  description string @description(\"A one line description of what's in the image\")\n  tags string[] @description(\"add 3,4 tags which fits the most eg. dashboard, product-screen etc\")\n}\n\nfunction AnalyzeImage(image: image) -> AssetAnalysis {\n  client OpenAIImageAnalysis\n  prompt #\"\n    Analyze the provided image in detail.\n\n    {{ ctx.output_format }}\n\n    {{ _.role(\"user\") }}\n    {{ image }}\n  \"#\n}\n",
	"animation_generator.baml": "class GenerateAnimationCodeRequest {\n  Prompt string @description(\"Visual animation blueprint generated earlier\")\n  VideoBranding VideoBranding\n}\n\nclass GenerateAnimationCodeResponse {\n  code string @description(\"Typescript code\")\n  total_frames int @description(\"total frames for this animation at 30fps\")\n  manualEdits string? @description(\"valid json\")\n  thinkingSummary string? @skip()\n}\n\nfunction GenerateAnimation(input: GenerateAnimationCodeRequest, conversation_history: Message[]) -> GenerateAnimationCodeResponse | AskUserQuestion {\n  client CustomGeminiProPreview\n  prompt #\"\n    You are an expert in generating React components for Remotion animations.\n\n    ## COMPONENT STRUCTURE\n\n    1. Start with ES6 imports\n    2. Export as: export default function RemoteComponent() { ... }\n    3. Component body order:\n       - Multi-line comment description (2-3 sentences)\n       - Hooks (useCurrentFrame, useVideoConfig, etc.)\n       - Constants (COLORS, TEXT, TIMING, LAYOUT) - all UPPER_SNAKE_CASE\n       - Calculations and derived values\n       - return JSX\n\n    ## CONSTANTS RULES (CRITICAL)\n   {% raw %}\n    ALL constants MUST be defined INSIDE the component body, AFTER hooks:\n    ```tsx\n    - Text: const TITLE_TEXT = \"Hello World\";\n    - Timing: const FADE_DURATION = 20;\n    - Layout: const PADDING = 40;\n    ```\n   {% endraw %}\n    This allows users to easily customize the animation.\n\n    ## LAYOUT RULES\n\n    - Use the full canvas with explicit dimensions from `useVideoConfig()`.\n    Required root pattern:\n    {% raw %}\n    ```tsx\n    const { width, height, fps } = useVideoConfig();\n\n    return (\n      <div\n        style={{\n          width,\n          height,\n          position: \"relative\",\n          overflow: \"hidden\",\n          fontFamily: \"Inter, sans-serif\",\n        }}\n      >\n        {/* animation */}\n      </div>\n    );\n    ```\n\n    * Use full width of the canvas with appropriate padding.\n    * Never constrain content to a small centered webpage-like box.\n    * Use `Math.max(minValue, Math.round(width * percentage))` for responsive sizing.\n    * Use `position: \"absolute\"` for animated elements.\n\n    ### Never generate\n\n    ```tsx\n    flex: 1\n    ```\n\n    ```tsx\n    width: \"100%\"\n    height: \"100%\"\n    ```\n\n    ```tsx\n    width: \"100vw\"\n    height: \"100vh\"\n    ```\n    {% endraw %}\n\n    Treat Remotion like a fixed-size animation canvas, not a responsive webpage.\n\n\n    ## ANIMATION RULES\n\n    - Prefer spring() for organic motion (entrances, bounces, scaling)\n    - Use interpolate() for linear progress (progress bars, opacity fades)\n    - Always use { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" }\n    - Add stagger delays for multiple elements\n\n    ## AVAILABLE IMPORTS\n\n   - You may import any icon from `lucide-react` if needed.\n\n   {% raw %}\n    \\`\\`\\`tsx\n    import { useCurrentFrame, useVideoConfig, interpolate, spring, Sequence } from \"remotion\";\n    import { useState, useEffect } from \"react\";\n    import { Text, LogoAsset, IconAsset, useTheme, MediaAsset } from './';\n    export default function RemoteComponent() {\n      return (\n            // Code goes here\n      );\n    }\n    \\`\\`\\`\n   {% endraw %}\n\n    ## RESERVED NAMES (CRITICAL)\n\n    NEVER use these as variable names - they shadow imports:\n    - spring, interpolate, useCurrentFrame, useVideoConfig, Sequence\n\n    ## STYLING RULES\n\n    - Use inline styles only\n    - ALWAYS use fontFamily: 'Inter, sans-serif'\n    - There is already a dark background on the canvas. Don't add any background\n\n    {{ AnimationPrimitives() }}\n\n    ## OUTPUT FORMAT (CRITICAL)\n\n    * If the prompt is ambiguous or visual details are unclear, ask for clarification using the **ask** tool. Do not assume missing creative direction.\n    * Always return the **total number of frames** for the animation.\n    * If `manualEdits` are provided in follow-up requests, always return the updated `manualEdits` along with the updated code.\n    * `manualEdits` reference code and elements by `elementId`. If a code change removes or renames an element so its ID no longer exists, remove the corresponding entry from `manualEdits`.\n\n   {{ BrandGuidelines(input.VideoBranding) }}\n\n    ---\n    ## INPUT\n\n    Resolution and Canvas Size:\n    16x9(1920x1080)\n\n    FPS:\n    30\n\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }}\n    {{ message.content }}\n    {{ message.images }}\n    {{ message.videos }}\n    {% endfor %}\n    {% endif %}\n\n    ---\n    {{ ctx.output_format }}\n  \"#\n}",
	"clients.baml":             "// Learn more about clients at https://docs.boundaryml.com/docs/snippets/clients/overview\n\nclient<llm> CustomGeminiProPreview {\n  provider google-ai\n  retry_policy Exponential\n  options {\n    model \"gemini-3.1-pro-preview\"\n    api_key env.GOOGLE_API_KEY\n    generationConfig { thinkingConfig { includeThoughts true } }\n  }\n}\n\nclient<llm> CustomGeminiFlash {\n  provider google-ai\n  retry_policy Exponential\n  options {\n    model \"gemini-2.5-flash\"\n    api_key env.GOOGLE_API_KEY\n  }\n}\n\nclient<llm> CustomClaudeOpus {\n  provider \"anthropic\"\n  retry_policy Exponential\n  options {\n    model \"claude-opus-4-6\"\n    api_key env.ANTHROPIC_API_KEY\n    max_tokens 12000\n    temperature 0.1\n  }\n}\n\nclient<llm> CustomOpenAI {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n  }\n}\n\nclient<llm> CustomOpenAI5 {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n    reasoning {\n      effort \"medium\"\n    }\n  }\n}\n\nclient<llm> CustomOpenAI5Nano {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4-mini\"\n    api_key env.OPENAI_API_KEY\n  }\n}\n\nclient<llm> OpenAIImageAnalysis {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4-mini\"\n    api_key env.OPENAI_API_KEY\n  }\n}\n\nclient<llm> CustomOpenAI5WithThinkingSummary {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n    reasoning {\n      effort \"medium\"\n      summary \"auto\"\n    }\n  }\n}\n\nclient<llm> CustomOpenAI55WithThinkingSummary {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.5\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n    reasoning {\n      effort \"medium\"\n      summary \"auto\"\n    }\n  }\n}\n\nclient<llm> CustomOpenAI5WithLowThinkingSummary {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n    reasoning {\n      effort \"low\"\n      summary \"auto\"\n    }\n  }\n}\n\n// https://docs.boundaryml.com/docs/snippets/clients/retry\nretry_policy Constant {\n  max_retries 3\n  strategy {\n    type constant_delay\n    delay_ms 200\n  }\n}\n\nretry_policy Exponential {\n  max_retries 2\n  strategy {\n    type exponential_backoff\n    delay_ms 300\n    multiplier 1.5\n    max_delay_ms 10000\n  }\n}",
	"common_helpers.baml":      "class Message {\n  role \"user\" | \"assistant\" | \"tool\"\n  content string\n  images image[]\n  videos video[]\n}\n\nenum AskUserQuestionType {\n  GENERIC @description(\"general clarification\")\n  ATTACHMENT_CLARIFICATION @description(\"when you need some clarification on an attached attachment\")\n  UPLOAD_ATTACHMENT @description(\"when you need to ask user to upload\")\n}\n\nclass AskUserQuestion {\n  tool_name \"ask_user_question\" @description(\"Use this tool to ask the user a question when you need clarification or additional information\")\n  questionType AskUserQuestionType\n  question_text string @description(\"The question to ask the user. Keep it concise (8 words or less).\")\n  options string[] @description(\"The answer choices for the user to select from\")\n  allow_custom_entry bool? @description(\"Whether to allow custom text entry in addition to the predefined options\")\n  attachmentUrl string? @description(\"attachment to get the clarification\")\n  thinkingSummary string? @skip()\n}\n\nclass VideoBranding {\n  brandGuideLines string? @description(\"user provided brand guidelines\")\n  brandColors string? @description(\"user provided brand tokens\")\n  attachments string?\n}\n\nclass Scene {\n  element SceneElement\n  background Background? @description(\"optional background\")\n  thinkingSummary string? @skip()\n}\n\nclass SceneElement {\n  component string\n  props string @description(\"required props in VALID JSON format as per the scene\")\n}\n\nenum ColorToken {\n  PRIMARY\n}\n\nclass Background {\n   solid ColorToken | string\n}",
	"common_prompts.baml":      "template_string BrandGuidelines(resume: VideoBranding) #\"\n    {% if resume.brandGuideLines %}\n    ### Brand Details:\n    {{ resume.brandGuideLines }}\n    {% endif %}\n\n    {% if resume.attachments %}\n    ### Attachments:\n    {{ resume.attachments }}\n    {% endif %}\n\"#\n\ntemplate_string BackgroundGuidelines(branding: VideoBranding) #\"\n   ### Background Guidelines\n   Background is an optional property. Most scenes don't need it.\n   Only use available color tokens unless user has asked for it.\n\n   Rules:\n   - Only specify background for high-impact scenes or when changing sections/topic:\n     - Hook\n     - Key reveal\n     - Main insight\n   - Do NOT add background for filler, pacing, or transition scenes.\n   - Do NOT apply back to back scenes.\n   - Keep usage minimal and consistent across the video.\n\"#\n\ntemplate_string EnterAnimation(animation: AnimationCategories) #\"\n    {% if animation.entranceAnimations %}\n    ### Available Entrance Animations:\n    {% for anim in animation.entranceAnimations %}\n    - {{ anim }}\n    {% endfor %}\n\n    ### Instructions:\n    Select the prop entranceAnimation for scenes that support it.\n\n    Guidelines:\n    - Do NOT invent new animations. Only use the ones provided above.\n    - Do NOT select randomly. Choose based on the scene's intent and tone.\n    - Keep consistency: use at most 2–3 animation styles across the entire video.\n    - Match animation to purpose:\n      - Subtle / professional → zoomIn, slideUp, scaleIn, slideDown\n      - Reveal / arrival → zoomIn\n      - Sequential content → slideUp, slideLeft, slideRight\n      - Playful emphasis → zoomIn, elasticScale\n      - Dramatic / high impact → rotateIn\n    {% endif %}\n\"#\n\n\ntemplate_string AnimationPrimitives() #\"\n\n    ### Typography:\n   - Use `Text` for all visible text. Never use `span`, `p`, `h1-h6`, or other text elements.\n   - Every `Text` component MUST have an `id`.\n   - The `id` of a `Text` component MUST start with `textasset-`, eg: `textasset-1`.\n   - Do not use any other prefix for `Text` component IDs.\n\n    {% raw %}\n    ```tsx\n    <Text id=\"textasset-1\" text=\"Hello\" style={{}} />\n    ```\n    {% endraw %}\n\n    ### Image, Video, Icon and Logo:\n    - Never use `img`, `video` or other media tags\n    - Use IconAsset for icons.\n    - Use LogoAsset for logos.\n    - Use MediaAsset for image or video.\n    - For `lucide-react` icons, import the icon component and pass it via the `Icon` prop.\n    - Every `IconAsset`, `LogoAsset`, `MediaAsset` component MUST have an `id` which start with `iconasset-`, `logoasset-`, `mediaasset-` respectively.\n    - Examples: `iconasset-1`, `logoasset-1`, `mediaasset-1`.\n\n    {% raw %}\n    ```tsx\n     import { Heart } from \"lucide-react\";\n     <IconAsset id=\"iconasset-1\" Icon={Heart} size={48} style={{}} />\n     <LogoAsset\n       id=\"logoasset-1\"\n       src=\"https://placehold.co/200x80.png\"\n       width={200}\n       height={80}\n       style={{}}\n     />\n     <MediaAsset\n        id=\"mediaasset-1\"\n        src=\"https://placehold.co/200x80.png\"\n        width={1200}\n        height={800}\n        style={{}}\n      />\n     ```\n    {% endraw %}\n\n    ### Branding\n    - Use useTheme() to access brand assets and color tokens.\n    - Use LogoAsset to render the logo or icon by passing the corresponding URL to src.\n    {% raw %}\n    ```tsx\n     const theme = useTheme();\n\n     // Brand colors\n     theme.colors.foreground // Primary text color\n     theme.colors.primary    // Brand/highlight color\n\n     // Brand assets\n     theme.logo.url\n     theme.logo.width\n     theme.logo.height\n\n     theme.logoIcon.url\n     theme.logoIcon.width\n     theme.logoIcon.height\n     ```\n    {% endraw %}\n\n    - Prefer theme.colors.foreground for text and theme.colors.primary for accents, highlights, and primary actions.\n    - Use theme.logo for the full logo and theme.logoIcon for compact/icon-only branding.\n\"#\n",
	"edit_animation.baml":      "enum AnimationCodeEditType {\n  TARGETED_EDITS @description(\"\")\n  FULL_REWRITE @description(\"\")\n}\n\nclass EditAnimationCodeRequest {\n  code string\n  prompt string\n}\n\nclass EditAnimationCodeResponse {\n  type AnimationCodeEditType\n  edits EditString[]\n}\n\nclass EditString {\n  description string @description(\"Brief description of this edit\")\n  oldString string @description(\"The exact string to find (must match exactly, including whitespace)\")\n  newString string @description(\"The replacement string\")\n}\n\nfunction EditAnimationCode(resume: EditAnimationCodeRequest, conversation_history: Message[]) -> EditAnimationCodeResponse {\n  client CustomOpenAI5\n  prompt #\"\n    You are an expert at making targeted edits to React components.\n\n    Given the current code and a user request, decide whether to:\n    1. Use targeted edits (for small, specific changes)\n    2. Provide full replacement code (for major restructuring)\n\n    ## WHEN TO USE TARGETED EDITS (type: TARGETED_EDITS)\n    - Changing colors, text, numbers, timing values\n    - Adding or removing a single element\n    - Modifying styles or properties\n    - Small additions (new variable, new element)\n    - Changes affecting <30% of the code\n\n    ## WHEN TO USE FULL REPLACEMENT (type: FULL_REWRITE)\n    - Completely different animation style\n    - Major structural reorganization\n    - User asks to \"start fresh\" or \"rewrite\"\n    - Changes affect >50% of the code\n\n    ## EDIT FORMAT\n    For targeted edits, each edit needs:\n    - old_string: The EXACT string to find (including whitespace/indentation)\n    - new_string: The replacement string\n\n    CRITICAL:\n    - old_string must match the code EXACTLY character-for-character\n    - Include enough surrounding context to make old_string unique\n    - If multiple similar lines exist, include more surrounding code\n    - Preserve indentation exactly as it appears in the original\n\n    --------------------------------------------------\n    INPUT\n    --------------------------------------------------\n\n    ## CURRENT CODE\n    {{ resume.code }}\n\n    ## USER REQUEST:\n    {{ resume.prompt }}\n\n    --------------------------------------------------\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    {{ ctx.output_format }}\n\n  \"#\n}",
	"generators.baml":          "// This helps use auto generate libraries you can use in the language of\n// your choice. You can have multiple generators if you use multiple languages.\n// Just ensure that the output_dir is different for each generator.\ngenerator target {\n    // Valid values: \"python/pydantic\", \"typescript\", \"go\", \"rust\", \"ruby/sorbet\", \"rest/openapi\"\n    output_type \"go\"\n\n    // Where the generated code will be saved (relative to baml_src/)\n    output_dir \"../\"\n\n    // The version of the BAML package you have installed (e.g. same version as your baml-py or @boundaryml/baml).\n    // The BAML VSCode extension version should also match this version.\n    version \"0.218.1\"\n\n    // 'baml-cli generate' will run this after generating go code\n    // This command will be run from within $output_dir/baml_client\n    on_generate \"gofmt -w . && goimports -w .\"\n\n    // Your Go packages name as specified in go.mod\n    // We need this to generate correct imports in the generated baml_client\n    client_package_name \"github.com/shank318/coasterai\"\n}\n",
	"match_categories.baml":    "class Category {\n  name string\n  description string @description(\"Clear explanation of the conceptual animation category. Describes the idea or scenario this category represents (e.g., data fragmentation, growth acceleration, workflow automation, before vs after transformation). Not a visual style.\")\n}\n\nclass MatchCategoriesRequest {\n  categories Category[] @description(\"Predefined conceptual animation categories to choose from. You must select only from this list.\")\n  query string @description(\"Concept or idea that needs to be mapped to the most relevant conceptual animation category.\")\n}\n\nclass MatchCategoriesResponse {\n  categories Category[] @description(\"matched category based on the query, return empty if no match found\")\n}\n\nfunction MatchCategories(resume: MatchCategoriesRequest) -> MatchCategoriesResponse {\n  // Specify a client as provider/model-name\n  // You can also use custom LLM params with a custom client name from clients.baml like \"client CustomGPT5\" or \"client CustomSonnet4\"\n  client CustomOpenAI5\n  prompt #\"\n  Category Matching Engine\n\n  You are a strict semantic classification engine.\n\n  Your task is to match the given query to one or more predefined conceptual categories.\n\n  You must ONLY select from the provided categories.\n  You must NEVER invent new categories.\n  You must NEVER modify category names or descriptions.\n\n  --------------------------------------------------\n  INPUT\n  --------------------------------------------------\n\n  Query:\n  {{ resume.query }}\n\n  Available Categories:\n  {% for category in resume.categories %}\n  - {{ category.name }}:\n    {{ category.description }}\n  {% endfor %}\n\n  --------------------------------------------------\n  MATCHING RULES\n  --------------------------------------------------\n\n  1. Understand the core concept expressed in the query.\n  2. Compare it against category descriptions.\n  3. Select categories that clearly represent the same conceptual idea.\n  4. Exclude categories that:\n     - Only partially match\n     - Are loosely related\n     - Represent visual style instead of concept\n     - Do not strongly align with the core idea\n\n  Be conservative:\n  If the match is unclear or weak, return an empty list.\n\n  If multiple categories clearly match, return them ordered by strongest relevance first.\n\n  --------------------------------------------------\n  IMPORTANT RULES\n  --------------------------------------------------\n\n  - Only return categories from the provided list.\n  - Do NOT create new categories.\n  - Do NOT explain reasoning.\n  - Do NOT include thinking.\n  - If none clearly match, return an empty array.\n\n  --------------------------------------------------\n  OUTPUT FORMAT\n  --------------------------------------------------\n\n  {{ ctx.output_format }}\n  \"#\n}",
	"scene_planner.baml":       "class ScriptItem {\n name string\n voiceover string?\n reference string?\n}\n\nclass AnimationCategories {\n  entranceAnimations string[]\n}\n\nclass VideoGenerationPlanRequest {\n    Duration int\n    Prompt string\n    Language string\n    Resolution string\n    Script  ScriptItem[]\n    VideoBranding VideoBranding\n    ComponentList string\n    AnimationCategories AnimationCategories\n    Questions map<string, string>\n}\n\nclass SceneSection {\n  name string @description(\"name of the section, around one or two words\")\n  slides Scene[]\n}\n\nclass GeneratedVideoPlan {\n    videoName string @description(\"name of the video, around 5 to 15 length\")\n    sections SceneSection[]\n    thinkingSummary string? @skip()\n}\n\nclass VideoGenerationPlan {\n  plan (GeneratedVideoPlan | AskUserQuestion)\n}\n\nfunction GeneratePlan(input: VideoGenerationPlanRequest, conversation_history: Message[]) -> VideoGenerationPlan {\n  client CustomOpenAI5WithThinkingSummary\n  prompt #\"\n    You are a cinematic video planning director. Your job is to decompose a video brief into a sequence of scenes.\n    You decide WHAT appears in each scene, HOW it behaves, and WHAT data it shows.\n    You do NOT write code.\n\n    ## VIDEO STRUCTURE\n\n    A good product video follows these sections. Map the user's script to these sections before planning scenes:\n\n    - **Hook/Intro** — grab attention immediately..\n    - **Problem** — articulate the pain point the product solves.\n    - **Solution** — introduce the product as the answer.\n    - **Product/Benefit Info** — show specific features, workflows, or how it works. This section can breathe.\n    - **Social Proof** — logos, metrics, testimonials that build trust.\n    - **CTA** — what to do next.\n\n    {{ input.ComponentList }}\n\n    ## SCENE DESIGN PRINCIPLES\n\n    - One idea per scene. Never combine two components in one scene.\n    - All scenes should feel connected, forming a continuous flow that maintains visual rhythm and tone.\n    - NEVER duplicate the same text across scenes\n    - Always use Logo scenes to introduce/revel the brand and the supporting text before the scene.\n    - Always finish with CTA scene.\n    - **Target 15–20 scenes total when possible, but avoid forcing unnecessary scenes and force fitting. Distribute across sections naturally based on\n      how much the script emphasizes each section. Do not pad sections artificially.**\n\n    Fillers work in any section. Use them to:\n    - Develop an idea within a section with scenes\n    - Add pacing between scenes\n    - Fill out scene count when a section needs more depth\n    - **When an appropriate scene is not available**\n\n    ## SCENE SELECTION\n\n    - Choose scenes/fillers based on how well they visually communicate each script segment.\n    - Select scenes using both section tags and underlying script meaning.\n    - *DO NOT repeat scenes.*\n    - *DO NOT force-fit scenes. Use a scene only if it supports the script visually and contextually.*\n    - Use `<attachments>` for image or video scenes. Use placeholders only when no attachments are provided.\n    - Divide/Split script text into scenes at logical sentence breaks. Do not split mid-sentence.\n        **Good**\n        * `AI is changing how teams work`\n        * `Most workflows are still manual`\n        **Bad**\n        * `AI is changing`\n        * `how teams work`\n\n    ### Data\n    Define scene props in `SceneElement` using JSON format.\n    - Use placeholder values when actual data is unavailable.\n    - Remove trailing commas, periods, and special characters from text.\n    - Never ever place large text blocks in a single scene. Limit each scene to:\n        **Max 2 lines**\n        **Max 10 words**\n        **50–55 characters maximum**\n    - For image or video placeholders, use: `https://placehold.co/{width}x{height}.png` where `width` and `height` are pixel values.\n\n    ## PLAN BEFORE EXECUTING\n\n    Before outputting scenes, reason through:\n\n    1. **Section mapping** — map or break the script into the appropriate sections?\n       Quote the relevant script portion for each section found.\n    2. Then break each video section further into multiple scenes or fillers.\n    3. **Narrative arc** — does the section order tell a coherent story?\n    4. **Hero vs supporting scenes** — which scenes carry the main message vs add pacing?\n    5. **Assets** — do any attachments match scene intent?\n    6. Use <attachments> and <user_note> to decide which attachment to use with Asset components.\n       pass the url as per props shape.\n\n    Only begin output after forming a clear plan.\n\n    ---\n\n    ## ASK QUESTIONS RULES\n\n    Ask before proceeding if:\n    - Missing critical sections would weaken the video (e.g., no Hook/CTA): ask whether to add them or proceed as-is.\n    - **Script is provided**: ask whether to use it exactly or allow light edits.\n    - Script-to-scene mapping is unclear: ask for clarification, or use the closest meaningful script subset.\n    - Brand presence is implied but no brand name/identity is provided: ask for brand identity.\n    - Attachment is provided but usage is unclear: use **ATTACHMENT_CLARIFICATION**.\n    - Scene requires a missing attachment: use **UPLOAD_ATTACHMENT or a placeholder**.\n    - A key visual storytelling decision is ambiguous.\n\n    Do not ask about:\n    - Props or component internals — the generator handles these.\n    - Sections the user clearly and intentionally omitted.\n\n    ## EXAMPLE SCENES\n    ```json\n    [\n      {\n        \"element\":\n          {\n            \"component\": \"AnimatedNumber\",\n            \"props\": \"{\\\"startText\\\": \\\"Solving\\\", \\\"endText\\\": \\\"incidents\\\", \\\"from\\\": 0, \\\"to\\\": 100}\"\n          }\n      },\n      {\n         \"element\":\n          {\n            \"component\": \"AnimatedImage\",\n             \"props\": \"{\\\"src\\\": \\\"@generated/ectplz/0.png\\\"}\"\n           }\n       }\n    ]\n    ```\n\n    {{ BrandGuidelines(input.VideoBranding) }}\n\n    {{ EnterAnimation(input.AnimationCategories) }}\n\n    ---\n\n    ## INPUT\n    Video FPS: 30 frames/second\n    Language: {{ input.Language }}\n\n    ### User provided prompt/script:\n    {{ input.Prompt }}\n\n    {%- if input.Questions -%}\n    ### Questions answered by the user:\n    {% for question in input.Questions -%}\n      {%- if input.Questions[question] %}\n      Q: {{ question }}\n      A: {{ input.Questions[question] }}\n      {%- endif %}\n    {%- endfor %}\n    {%- endif %}\n\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    {{ ctx.output_format }}\n  \"#\n}",
	"suggest_scenes.baml":      "class SuggestScenesRequest {\n  VideoBranding VideoBranding\n  ComponentList string\n  Category string\n  before string\n  current string\n  after string\n}\n\nclass SuggestScenesResponse {\n  scenes Scene[]\n}\n\n\nfunction SuggestScenes(input: SuggestScenesRequest) -> SuggestScenesResponse {\n  client CustomGeminiFlash\n\n  prompt #\"\n    You are an expert cinematic video editor.\n\n    Your task is to suggest alternative scenes for the current scene.\n\n    You are given:\n    - the current scene\n    - optionally the previous scene\n    - optionally the next scene\n    - a list of available components\n    ---\n\n    ## AVAILABLE COMPONENTS\n\n    {{ input.ComponentList }}\n\n    ---\n\n    ## RULES\n\n    ### Scene Structure\n    Each scene MUST follow this exact structure:\n\n    ```json\n    {\n      \"element\": {\n        \"component\": \"ComponentName\",\n        \"props\": \"{...json string...}\"\n      }\n    }\n    ```\n\n    ### Props Rules\n    - `props` MUST be a valid JSON string\n    - Only use components from the available component list\n\n    ### Image Rules\n    For placeholder images use:\n    https://placehold.co/{width}x{height}.png\n\n    ### Output Rules\n    - Primarily use the text, media assets, and data already present in the CURRENT scene props(eg. text, words, src etc)\n    - If some data is missing, you may derive or infer it using the previous or next scenes\n    - NEVER copy text directly from the previous or next scenes, previous and next scenes are only for contextual understanding\n    - Generate 3-5 scene suggestions\n    - DO NOT return duplicate component irrespective of props.\n\n    ---\n\n    ## EXAMPLE\n\n    [\n      {\n        \"element\": {\n          \"component\": \"AnimatedNumber\",\n          \"props\": \"{\\\"startText\\\":\\\"Solving\\\",\\\"endText\\\":\\\"incidents\\\",\\\"from\\\":0,\\\"to\\\":100}\"\n        }\n      },\n      {\n        \"element\": {\n          \"component\": \"AnimatedImage\",\n          \"props\": \"{\\\"src\\\":\\\"@generated/ectplz/0.png\\\"}\"\n        }\n      }\n    ]\n\n    ---\n\n    {{ BrandGuidelines(input.VideoBranding) }}\n\n    ## INPUT\n\n    {% if input.current %}\n    ### Current Scene\n    {{ input.current }}\n    {% endif %}\n\n    {% if input.before %}\n    ### Previous Scene\n    {{ input.before }}\n    {% endif %}\n\n    {% if input.after %}\n    ### Next Scene\n    {{ input.after }}\n    {% endif %}\n\n    {% if input.Category %}\n    ### Animation Type\n    {{ input.Category }}\n    {% endif %}\n\n    ---\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
}

func getBamlFiles() map[string]string {
	return file_map
}
